// Test the bucket_less_than function implementation
#include <string>
#include <vector>
#include <cmath>
#include <algorithm>

bool bucket_less_than(const std::string& lhs_name, const std::vector<float>& lhs_points, const std::string& rhs_name, const std::vector<float>& rhs_points) {
    // First compare by name lexicographically
    if (lhs_name != rhs_name) {
        return lhs_name < rhs_name;
    }

    // Names are equal, compare partition points with epsilon tolerance
    const float epsilon = 1e-6f;

    // Compare vectors element by element
    size_t min_size = std::min(lhs_points.size(), rhs_points.size());

    for (size_t i = 0; i < min_size; ++i) {
        float lhs_val = lhs_points[i];
        float rhs_val = rhs_points[i];

        // Check if values are different within epsilon tolerance
        if (std::abs(lhs_val - rhs_val) > epsilon) {
            return lhs_val < rhs_val;
        }
    }

    // All compared elements are equal within tolerance
    // Shorter vector comes first
    return lhs_points.size() < rhs_points.size();
}

