    // Test 1: Different names
    std::string name1 = "bucket_a";
    std::string name2 = "bucket_b";
    std::vector<float> points1 = {1.0f, 2.0f};
    std::vector<float> points2 = {1.0f, 2.0f};

    bool result1 = bucket_less_than(name1, points1, name2, points2);

    // Test 2: Same names, different points
    std::string name3 = "bucket";
    std::vector<float> points3 = {1.0f, 2.0f};
    std::vector<float> points4 = {1.1f, 2.0f};

    bool result2 = bucket_less_than(name3, points3, name3, points4);

    // Test 3: Same names, same points within epsilon
    std::vector<float> points5 = {1.000001f, 2.0f};
    std::vector<float> points6 = {1.0f, 2.0f};

    bool result3 = bucket_less_than(name3, points5, name3, points6);

    // Test 4: Different vector lengths
    std::vector<float> points7 = {1.0f};
    std::vector<float> points8 = {1.0f, 2.0f};

    bool result4 = bucket_less_than(name3, points7, name3, points8);

    return 0;
}

